/* All routes and renderers are included in each embed. No remote script, API key or build dependency is needed. */
'use strict';
const CORE=[['home','ホーム'],['consult','相談する'],['ai-guide','教育支援ナビ'],['concerns','困りごとから探す'],['school-life','不登校・学校生活'],['development','発達の特性'],['reports','活動REPORT'],['staff','講師紹介'],['support','支援機関を探す'],['about','センターについて'],['booking','相談予約'],['faq','よくある質問'],['contact','お問い合わせ'],['privacy','プライバシーについて'],['site-policy','サイトポリシー'],['ai-policy','AI利用について']];
const ROUTES=Object.fromEntries([...CORE,...DATA.articles.map(a=>[a.id,a.title]),...DATA.reports.map(a=>[a.id,a.title])]);
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(v,allowData=false){try{if(allowData&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(v))return v;const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return ''}}
function fileName(id){return id==='home'?'/kodomo-education-support/':'/kodomo-education-support/'+id+'/'}
function routeAttrs(id){
 if(!Object.hasOwn(ROUTES,id))throw Error('Unknown route '+id);
 if(CONFIG.navigation==='site')return `href="${E(fileName(id))}" data-page="${E(id)}"`;
 const published=safeURL(CONFIG.routes?.[id]);
 if(published)return `href="${E(published)}" target="_blank" rel="noopener noreferrer" data-page="${E(id)}" data-external-page="true"`;
 if(CONFIG.navigation==='files')return `href="${E(fileName(id))}" data-page="${E(id)}"`;
 return `href="#page=${encodeURIComponent(id)}" data-page="${E(id)}" data-internal="true"`;
}
function link(id,text,cls=''){const ext=safeURL(CONFIG.routes?.[id]);return `<a ${routeAttrs(id)} class="${E(cls)}"${ext?' aria-label="'+E(text)+'（別タブで開きます）"':''}>${E(text)}${ext?'<span class="new-tab">（別タブ）</span>':''}</a>`}
function external(url,text,cls='btn secondary'){const u=safeURL(url);if(!u)return '';return `<a href="${E(u)}" target="_blank" rel="noopener noreferrer" class="${E(cls)}" aria-label="${E(text)}（別タブで開きます）">${E(text)} <span class="new-tab">（別タブ）</span></a>`}
const icons={
 phone:'<path d="M7 3H4a1 1 0 0 0-1 1c0 9 8 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a14 14 0 0 1-7-7l2-2Z"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 chat:'<path d="M4 4h16v12H9l-5 4Z"/><path d="M8 9h8m-8 3h5"/>',
 school:'<path d="m3 10 9-7 9 7M5 9v12h14V9M10 21v-6h4v6M9 11h6"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
 people:'<circle cx="9" cy="8" r="3"/><circle cx="18" cy="9" r="2"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-6a4 4 0 0 1 4 4v2"/>',
 book:'<path d="M12 5v16M3 4h5l4 2 4-2h5v15h-5l-4 2-4-2H3Z"/>',
 sound:'<path d="M3 9h4l5-5v16l-5-5H3Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',
 focus:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><circle cx="12" cy="12" r="3"/>',
 heart:'<path d="M12 21 3 12C-2 4 7 0 12 6c5-6 14-2 9 6Z"/>',
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',
 leaf:'<path d="M5 20C2 7 11 3 21 3c0 10-4 19-16 17Zm0 0L16 8"/>',
 person:'<circle cx="12" cy="7" r="4"/><path d="M3 22v-3a9 9 0 0 1 18 0v3"/>',
 building:'<path d="m3 9 9-6 9 6M3 21h18M5 11v7m7-7v7m7-7v7"/>'
};
function icon(name,cls='icon'){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`}
function photo(id,mode='lead'){const p=PHOTOS[id];if(!p)return '';const report=id==='reports'||id.startsWith('reports/');return `<figure class="page-photo ${mode}-photo"><img src="/kodomo-education-support/assets/${E(p.asset)}.webp" alt="${E(p.alt)}" width="1200" height="800" ${mode==='card'?'loading="lazy" decoding="async"':'fetchpriority="high"'}>${mode==='card'?(report?'<figcaption>AI生成の活動イメージ。実際の開催写真ではありません。</figcaption>':id==='staff'?'<figcaption>人物はAI生成のイメージです。</figcaption>':''):`<figcaption>${report?'活動テーマのイメージ（AI生成）。実際の開催写真ではありません。':'AI生成のイメージ写真'}</figcaption>`}</figure>`}
function heroArt(){return photo('home','hero')}
function section(title,body,tone='',intro='',id=''){return `<section${id?' id="'+E(id)+'"':''} class="section ${tone}"><div class="wrap">${title?'<h2>'+E(title)+'</h2>':''}${intro?'<p class="intro">'+E(intro)+'</p>':''}${body}</div></section>`}
function actions(...items){return `<div class="actions">${items.join('')}</div>`}
function card(title,text,id,button,ico='leaf',tone='',btnTone=''){return `<article class="card ${tone}">${icon(ico)}<h3>${E(title)}</h3><p>${E(text)}</p>${actions(link(id,button,'btn '+btnTone))}</article>`}
function articleCards(parent,tiles=false){return `<div class="grid ${tiles?'g4':'g3'}">${DATA.articles.filter(a=>a.parent===parent).map(a=>tiles?`<a ${routeAttrs(a.id)} class="tile photo-tile">${photo(a.id,'card')}<span>${E(a.title)}</span></a>`:card(a.title,a.summary,a.id,'この情報を見る',a.icon).replace('<article class="card ">','<article class="card photo-card">'+photo(a.id,'card'))).join('')}</div>`}
function faqBlock(limit=8){return `<div class="faq">${DATA.faqs.slice(0,limit).map(([q,a,id])=>`<details><summary>${E(q)}</summary><p>${E(a)} ${link(id,'関連する案内を見る')}</p></details>`).join('')}</div>`}
function reportCards(){return `<div class="grid g2">${DATA.reports.map(a=>`<article class="card photo-card">${photo(a.id,'card')}<span class="pill">活動報告</span><p class="date">${E(a.date)}</p><h3>${E(a.title)}</h3><p>${E(a.summary)}</p>${actions(link(a.id,'この活動の内容を見る','btn secondary'))}</article>`).join('')}</div>`}
function staffCards(){return `<div class="grid g2">${[['A氏（男性）','lecturer-a','親子と学校をつなぐ、対話の進め方'],['B氏（女性）','lecturer-b','子どもの気持ちを聴く、安心できる関わり方']].map(([name,asset,theme])=>`<article class="card lecturer-preview"><img src="/kodomo-education-support/assets/${asset}.webp" alt="${E(name)}の架空の顔写真（AI生成）" width="640" height="640" loading="lazy"><span class="pill">架空の講師 · 紹介例</span><h3>${E(name)}</h3><p>${E(theme)}</p>${actions(link('staff','講師紹介を見る','btn secondary'))}</article>`).join('')}</div>`}
function supportCategories(){return `<div class="grid g3">${[['行政・公的相談','地域別の相談窓口を探します。','building'],['教育支援センター','学校生活や学びの相談先を探します。','school'],['発達支援','地域の専門窓口を探します。','focus'],['子育て支援','家族の困りごとについて相談先を探します。','heart'],['児童相談','児童相談所の情報を確認します。','people'],['緊急時の窓口','今すぐ必要な相談先を確認します。','phone']].map(([t,d,i])=>card(t,d,'support','支援機関を探す',i)).join('')}</div>`}
function header(id){return `<a href="#main" class="skip">本文へ移動する</a><header class="site-header"><div class="wrap header-inner">${link('home','子ども教育支援センター','brand').replace('>子ども',`>${icon('leaf')}子ども`)}<button type="button" class="menu-button" aria-controls="primary-nav" aria-expanded="false">メニュー</button><nav id="primary-nav" class="nav" aria-label="主なメニュー">${[['consult','相談する'],['ai-guide','教育支援ナビ'],['concerns','情報を探す'],['reports','活動REPORT'],['staff','講師紹介'],['about','センターについて']].map(([k,t])=>link(k,t).replace('class=""',`class=""${id===k?' aria-current="page"':''}`)).join('')}</nav></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="grid g3"><div><h2>子ども教育支援センター</h2><p>小学生・中学生・高校生、その保護者、小中高の先生が、今の状況に合う情報や相談先を探すための教育支援ポータルです。</p>${CONFIG.operator?'<p>運営：'+E(CONFIG.operator)+'</p>':''}${link('about','活動と運営情報を見る')}</div><div><h3>相談と情報</h3><div class="footer-links">${[['consult','相談する'],['ai-guide','教育支援ナビ'],['concerns','困りごとから探す'],['school-life','不登校・学校生活'],['development','発達の特性'],['support','支援機関を探す'],['staff','講師紹介'],['booking','教育相談予約（体験）'],['reports','活動REPORT'],['contact','お問い合わせ']].map(([k,t])=>link(k,t)).join('')}</div></div><div><h3>サイトについて</h3><div class="footer-links">${[['faq','よくある質問'],['privacy','プライバシーについて'],['site-policy','サイトポリシー'],['ai-policy','AI利用について']].map(([k,t])=>link(k,t)).join('')}</div></div></div><p class="photo-disclosure">掲載写真はAI生成のイメージです。実際の施設・人物・活動の写真ではありません。</p><div class="footer-bottom"><span class="small">© 子ども教育支援センター</span>${link('home','ホームへ戻る')}</div></div></footer>`}
function home(){return `<main id="main" tabindex="-1">
 <section class="section sky"><div class="wrap hero"><div><p class="eyebrow">小中高校生・保護者・先生のための教育支援ポータル</p><h1>子どもと家族の<br>「これから」を、<br>一緒に考える。</h1><p>学校生活や学び方のことで迷っているとき。今の状況に合う情報や相談先を、ここから探してみませんか。</p>${actions(link('consult','相談方法を見る','btn'),link('concerns','困りごとから探す','btn secondary'))}</div>${heroArt()}</div></section>
 ${section('子ども教育支援センターとは',`<div class="intro-split"><div><p>小学生・中学生・高校生の健全育成を目指し、教育問題全般について研究し、情報共有と実践活動を行う教育機関です。本人・保護者・先生が次の選択肢を考えるための情報や相談の入口をご案内します。</p>${link('about','センターの活動と運営について','btn secondary')}</div><div class="center">${icon('leaf','portrait')}<p>一人ひとりの状況から、<br>次の選択肢を考えます。</p></div></div>`,'mint')}
 ${section('あなたの立場から探す',audienceCards())}
 ${section('高校の転校・転学・退学を考えている方へ',`<p>今の学校がつらい、学び方を変えたい、退学を迷っている。まだ決めていなくても、すでに退学していても、相談と情報探しの入口があります。</p>${actions(link('school-life/future','転校・転学・退学の案内を見る','btn secondary'),link('consult','人に相談する','btn green'))}`,'sky')}
 ${section('あなたに合った方法で探せます',`<div class="grid g3">${card('相談したい','人に話して、一緒に考えたい方へ。対象や相談方法をご案内します。','consult','相談方法を見る','phone','mint','green')}${card('困りごとから探す','学校生活や家庭での困りごとに合う情報を探せます。','concerns','困りごとから探す','search','sand')}${card('話しながら探す','選択肢と短い言葉で、情報や相談先を探せる体験版です。','ai-guide','教育支援ナビを使う','chat','sky','ai')}</div>`)}
 ${section('教育支援ナビで、一つずつ探す',`<div class="grid g2"><div><p>困りごとが、うまく言葉にならなくても大丈夫です。体験版では、選択肢と短い言葉で、関連する情報や人への相談方法を探せます。</p>${actions(link('ai-guide','教育支援ナビを使う','btn ai'),link('consult','人への相談方法を見る','btn secondary'))}<p class="note">体験版は実際のAIには接続していません。診断や緊急対応は行いません。</p></div><div class="chat-example"><p class="muted">案内のイメージ</p><div class="bubble user">学校に行きづらいときの情報を知りたい</div><div class="bubble">関連する情報と、相談方法への入口をご案内します。</div>${link('ai-guide','AI利用について確認する')}</div></div>`,'sky')}
 ${section('こんなことで困っていませんか',articleCards('concerns',true),'','今、気になることから選んでください。複数の困りごとがあってもかまいません。')}
 ${section('相談したい方へ',`<div class="grid g2">${card('電話で相談したい方へ','小中高校生本人・保護者・先生が利用条件を確認し、人に相談する入口です。','consult','電話相談の受付を確認する','phone','','green')}${card('予約してオンラインで相談したい方へ','対象学年や相談できる内容、利用方法をご確認のうえ、お申し込みください。','booking','予約相談の対象と方法を見る','chat')}</div>`,'gray','相談方法によって、対象や受付条件が異なります。ご希望の方法をご確認ください。')}
 ${section('予約して相談したい方へ',`<p class="intro">カレンダーで日時を選び、相談する方と相談内容を選ぶ操作を試せます。体験画面から実際の予約は受け付けません。</p>${link('booking','教育相談予約を体験する','btn green')}`,'mint')}
 ${section('不登校や学校生活について知る',articleCards('school-life')+actions(link('school-life','学校生活の情報をもっと見る','btn secondary')),'','学校との関わり方や、家庭での過ごし方、学びの選択肢を知るための情報をまとめています。気になるテーマからご覧ください。')}
 ${section('発達の特性について知る',articleCards('development')+`<p class="note">このサイトやAIによって診断を行うことはできません。</p>`,'gray','発達の特性について理解し、学校や家庭での困りごとを考えるための情報をご案内します。特性の現れ方や必要な支援は、一人ひとり異なります。')}
 ${section('活動REPORT',reportCards()+actions(link('reports','活動REPORTをすべて見る','btn secondary')),'','センターの活動や、学びと支援に関する取り組みをご紹介します。')}
 ${section('講師紹介',staffCards()+actions(link('staff','講師紹介と派遣依頼を見る','btn secondary'),link('staff','講師の電話依頼について見る','btn green')),'mint','相談会・フォーラム等への講師派遣をご案内します。A氏・B氏は架空の紹介例です。')}
 ${section('相談・支援機関を探す',supportCategories()+actions(link('support','地域や分野から支援機関を探す','btn')),'gray','小中高校生・保護者・先生が、地域や困りごとに合う公的窓口や学びの相談先を探せます。センター以外の相談先も含めてご案内します。')}
 ${section('よくある質問',faqBlock(6)+actions(link('faq','よくある質問をすべて見る','btn secondary')))}
 </main>`}
function lead(id,intro,parent='home'){return `<section class="page-lead"><div class="wrap lead-grid"><div><nav class="breadcrumb" aria-label="現在位置">${link('home','ホーム')}<span aria-hidden="true">›</span>${parent!=='home'?link(parent,ROUTES[parent])+'<span aria-hidden="true">›</span>':''}<span aria-current="page">${E(ROUTES[id])}</span></nav><h1 id="page-title">${E(ROUTES[id])}</h1><p class="intro">${E(intro)}</p></div>${photo(id)}</div></section>`}
function subpage(id,intro,body,parent='home',wide=false){return `<main id="main" tabindex="-1">${lead(id,intro,parent)}<section class="section"><div class="wrap ${wide?'':'article'}">${body}<div class="back-row">${link(parent,parent==='home'?'ホームへ戻る':ROUTES[parent]+'へ戻る','btn secondary')}${id==='consult'?link('booking','予約相談の案内を見る','btn green'):link('consult','相談方法を見る','btn green')}</div></div></section></main>`}
function sources(ids){return `<h2>参考情報</h2><ul class="source-list">${ids.map(k=>DATA.sources[k]).filter(Boolean).map(s=>`<li>${external(s.url,s.label,'')}</li>`).join('')}</ul><p class="meta">参考ページ確認日：2026年10月1日</p>`}
function article(a){return subpage(a.id,a.summary,`<p>このページでは、相談で確認したいことと、関連する情報の入口をまとめています。状況によって必要な対応は異なります。</p>${a.sections.map(([title,paras])=>'<h2>'+E(title)+'</h2>'+paras.map(t=>'<p>'+E(t)+'</p>').join('')).join('')}<h2>関連する情報</h2><div class="grid g2">${a.related.map(id=>card(ROUTES[id],'気になる情報や相談方法を確認できます。',id,'案内を見る','leaf')).join('')}</div>${audienceArticle(a)}${learningLinks(a.id)}${sources(a.sources)}${CONFIG.articleCredit?'<p class="author-note">'+E(CONFIG.articleCredit)+'</p>':''}`,a.parent)}

function audienceLink(key,label){return link('concerns',label,'btn secondary').replace('href="/kodomo-education-support/concerns/"','href="/kodomo-education-support/concerns/#'+key+'"')}
function audienceCards(){return `<div class="grid g3">${[['student','小学生・中学生・高校生のあなたへ','学校、友達、勉強、これからのこと。気になることから探せます。'],['parent','保護者の方へ','本人の気持ちと、ご家族が心配していることから考えます。'],['teacher','小中高の先生へ','学校での支援、家庭との連携、研修・講師派遣の情報を確認できます。']].map(([key,title,text])=>`<article class="card"><h3>${E(title)}</h3><p>${E(text)}</p>${audienceLink(key,'この立場の案内を見る')}</article>`).join('')}</div>`}
function audienceHub(){return `<div class="audience-hub"><section id="student"><h2>小学生・中学生・高校生のあなたへ</h2><p>うまく説明できなくても大丈夫です。小学生は話しやすい大人と一緒に、中高生は自分の気になることから探せます。</p>${actions(link('concerns/school','学校に行きづらい','btn secondary'),link('concerns/friends','友達のこと','btn secondary'),link('concerns/learning','勉強のこと','btn secondary'),link('concerns/future','高校進学・これからの進路','btn secondary'),link('school-life/future','高校の転校・転学・退学のこと','btn secondary'),link('consult','人に相談したい','btn green'))}</section><section id="parent"><h2>保護者の方へ</h2><p>本人の希望とご家族の心配を、分けて整理できます。登校や進路の結論を急がず、確認したいことから相談できます。</p>${actions(link('concerns/parenting','子どもへの関わり方','btn secondary'),link('school-life/alternatives','学校以外の学び方','btn secondary'),link('school-life/future','高校の転学・退学の迷い','btn secondary'),link('booking','相談予約の体験','btn secondary'),link('support','地域や学びの相談先','btn secondary'))}</section><section id="teacher"><h2>小中高の先生へ</h2><p>本人・保護者の意向を聞き、学校でできる支援と外部の相談先を一緒に確認する入口です。児童生徒の名前・学校名・相談記録は入力しないでください。</p>${actions(link('development/school-support','学校での支援を考える','btn secondary'),link('school-life/learning','課題・単位の確認','btn secondary'),link('school-life/future','高校の転学・退学の相談','btn secondary'),link('support','外部の相談先','btn secondary'),link('staff','研修・講師派遣','btn secondary'),link('reports','活動レポートと投稿体験','btn secondary'),link('consult','教育相談の案内','btn green'))}</section></div>`}
function audienceArticle(a){const school=a.parent==='development'?'席・教材・説明の方法など、本人が過ごしやすい条件を確認します。診断名だけで支援を決めず、必要に応じて専門窓口と連携します。':a.id.includes('future')?'本人の希望を確認し、進学先・転学先の担当者と、募集条件や必要書類を確かめます。':'本人が困っている場面と、取り組みやすい条件を確かめ、家庭との連絡方法や校内の相談窓口を整理します。';return `<details class="audience-note"><summary>本人・保護者・先生、それぞれの使い方</summary><p><strong>小中高校生本人：</strong>気になるところだけ読んでください。小学生や、一人では話しづらいときは、信頼できる大人と一緒に相談できます。言いたくないことを全部話す必要はありません。</p><p><strong>保護者：</strong>本人の希望と、ご家族の心配を分けて伝えられます。本人が共有してよい範囲も確認しましょう。</p><p><strong>小中高の先生：</strong>${E(school)}</p>${actions(link('concerns','立場ごとの案内を見る','btn secondary'),link('consult','人に相談する','btn green'))}</details>`}
const LEARNING_SUPPORTS=[
{name:'埼玉県総合教育センター',reading:'さいたま',url:'https://www.pref.saitama.lg.jp/soshiki/g2205/index.html',text:'教育相談を扱う公的機関。相談窓口・対象・申込方法を県の公式案内から確認できます。',category:'consult',kind:'公的相談'},
{name:'千葉県の教育相談窓口',reading:'ちば',url:'https://www.pref.chiba.lg.jp/kyouiku/shidou/soudan/soudan11.html',text:'子どもと親のサポートセンターや教育相談室などを案内しています。地域・相談内容に合う窓口を確認できます。',category:'consult',kind:'公的相談'},
{name:'東京都教育相談センター',reading:'とうきょう',url:'https://e-sodan.metro.tokyo.lg.jp/',text:'学校生活や高校の進級・進路・入学などの相談窓口。相談内容に応じた方法・対象を確認できます。',category:'consult',kind:'公的相談'},
{name:'地域の不登校相談窓口（文部科学省）',reading:'ちいき',url:'https://www.mext.go.jp/a_menu/shotou/seitoshidou/06112214.html',text:'お住まいの地域の相談先を探すための公的な案内です。担当地域や利用条件は各窓口に確認できます。',category:'consult',kind:'全国の窓口案内'},
{name:'WISH個別指導教室',reading:'うぃっしゅ',url:'https://www.wishkobetsu.jp/',text:'個別指導教室。対象学年・指導内容・通い方・費用を公式案内で確認できます。',category:'facility',kind:'学習教室'},
{name:'公文式教室',reading:'くもん',url:'https://www.kumon.ne.jp/',text:'学習教室。近くの教室、教科、学習方法、費用を公式案内で確認できます。',category:'facility',kind:'学習教室'},
{name:'東京シューレ',reading:'とうきょう',url:'https://www.shure.or.jp/',text:'フリースクール。活動場所・対象年齢・過ごし方・入会条件・費用を確認できます。',category:'facility',kind:'フリースクール'},
{name:'家庭教師のトライ',reading:'かていきょうし',url:'https://www.trygroup.co.jp/',text:'家庭やオンラインでの学習支援。対象・指導方法・費用を公式案内で確認できます。',category:'facility',kind:'訪問・オンライン学習支援'},
{name:'早稲田自由スクール',reading:'わせだ',url:'https://www.fswaseda.jp/',text:'小学校4年生～中学校3年生向けのフリースクール。在籍校との関わり・利用条件・費用を確認できます。',category:'facility',kind:'フリースクール'},
{name:'NHK学園高等学校',reading:'えぬえいちけい',url:'https://www.n-gaku.jp/sch/',text:'通信制高校。学習方法・スクーリング・入学や転編入の条件・費用を確認できます。',category:'school',kind:'通信制高校'},
{name:'N高等学校・S高等学校・R高等学校',reading:'えぬこう',url:'https://nnn.ed.jp/',text:'通信制高校。各校のコース・通学方法・入学や転編入の条件・費用を確認できます。',category:'school',kind:'通信制高校'},
{name:'鹿島学園高等学校など（鹿島教育グループ）',reading:'かしま',url:'https://kg-school.net/',text:'通信制高校の公式案内。学校ごとの学習方法・入学や転編入の条件・費用を確認できます。',category:'school',kind:'通信制高校'},
{name:'クラーク記念国際高等学校',reading:'くらーく',url:'https://www.clark.ed.jp/',text:'通信制高校。キャンパス・コース・入学や転編入の条件・費用を確認できます。',category:'school',kind:'通信制高校'},
{name:'第一学院高等学校',reading:'だいいち',url:'https://www.daiichigakuin.ed.jp/',text:'通信制高校。通学やオンラインの学習方法・入学や転編入の条件・費用を確認できます。',category:'school',kind:'通信制高校'},
{name:'わせがく高等学校',reading:'わせがくこう',url:'https://www.wasegaku.ac.jp/',text:'通信制高校。学習方法・入学や転編入の条件・費用を公式案内で確認できます。',category:'school',kind:'通信制高校'},
{name:'わせがくPURE高等学校',reading:'わせがくぴゅあ',url:'https://www.pure.wasegaku.ac.jp/',text:'通信制高校。学習方法・入学や転編入の条件・費用を公式案内で確認できます。',category:'school',kind:'通信制高校'},
{name:'わせがく夢育高等学校',reading:'わせがくゆめ',url:'https://www.yumeiku.wasegaku.ac.jp/',text:'通信制高校。学習方法・入学や転編入の条件・費用を公式案内で確認できます。',category:'school',kind:'通信制高校'}];
const LEARNING_CATEGORIES=[
{id:'consult',label:'相談機関',text:'困りごとの整理や、利用できる支援について話したいとき。',note:'地域によって利用できる窓口や対象が異なります。全国の窓口案内も使って、お住まいの地域から探せます。'},
{id:'facility',label:'支援施設',text:'学校以外の居場所や、教室・家庭での学習支援を探したいとき。',note:'フリースクールと学習教室・家庭教師では、活動内容や目的が異なります。学校の卒業資格を出す機関とは区分が異なります。',directory:['https://freeschoolnetwork.jp/','全国のフリースクールを探す（加盟団体一覧）']},
{id:'school',label:'学校',text:'進学、転校・転学、退学後の学び直しについて確認したいとき。',note:'通信制高校の個別の例に加え、公立・私立の学びの多様化学校を探す公式一覧も確認できます。全日制・定時制なども含めた進路の相談は、相談機関から探せます。',directory:['https://www.mext.go.jp/a_menu/shotou/seitoshidou/1387004.htm','公立・私立の学びの多様化学校を探す（文部科学省）']}
];
function learningSupportList(filterable=true){return `<section class="learning-supports${filterable?' support-item':''}"${filterable?' data-category="education"':''}><h2>学びの場・学習について相談する</h2><p>まず、探したい相談先の種類を選んでください。選んだ項目を開くと、複数の機関・施設・学校から確認できます。</p><div class="learning-choices">${LEARNING_CATEGORIES.map(c=>{const entries=LEARNING_SUPPORTS.filter(x=>x.category===c.id).sort((a,b)=>a.reading.localeCompare(b.reading,'ja'));return `<details class="learning-choice" name="learning-category"><summary><span class="learning-choice-title">${E(c.label)}</span><span class="learning-choice-description">${E(c.text)}</span><span class="learning-choice-hint">選択肢を開く</span></summary><div class="learning-choice-body"><h3>${E(c.label)}の選択肢</h3><p class="note">${E(c.note)}</p><ul class="source-list">${entries.map(x=>`<li><span class="learning-kind">${E(x.kind)}</span>${external(x.url,x.name,'')}<p>${E(x.text)}</p></li>`).join('')}</ul>${c.directory?`<div class="learning-directory">${external(c.directory[0],c.directory[1],'')}<p>一覧から、地域や対象に合う候補をさらに探せます。</p></div>`:''}</div></details>`}).join('')}</div><p class="note">掲載先は選択肢の例です。各一覧は名称の読み順で、順位や推奨度を示しません。対象学年・地域・通い方・費用・在籍校との連携を比べて確認してください。高校の転入・編入、出席・単位の扱いは在籍校と希望先に確認できます。公式ページ確認日：2026年10月2日</p></section>`}
function learningLinks(id){return ['school-life/alternatives','school-life/future','concerns/future','concerns/learning'].includes(id)?learningSupportList(false):''}

function supportBody(){return `<p>窓口の対象・費用・受付時間は、公式ページの最新案内をご確認ください。掲載先への紹介や予約をこのページで代行するものではありません。</p><div class="toolbar"><label class="field">地域を選ぶ<select id="region"><option value="all">全国の窓口から探す</option><option value="chiba">千葉県</option><option value="saitama">埼玉県</option><option value="tokyo">東京都</option><option value="ibaraki">茨城県</option></select></label><label class="field">分野を選ぶ<select id="category"><option value="all">すべて</option><option value="education">教育・学校生活</option><option value="development">発達支援</option><option value="family">子育て・児童相談</option><option value="urgent">緊急時の相談</option></select></label></div><p class="status" id="support-status" role="status"></p><div id="regional-links"></div><div id="support-items">${[
 ['education','不登校の相談窓口','文部科学省','全国／地域の対象は公式情報をご確認ください','不登校・学校生活','https://www.mext.go.jp/a_menu/shotou/seitoshidou/06112214.html','地域の教育相談を探す'],
 ['development','発達障害者支援センター','国立障害者リハビリテーションセンターの一覧','全国／地域ごとの相談窓口','発達に関する困りごと','https://www.rehab.go.jp/ddis/action/center/','地域の専門窓口を探す'],
 ['family','こども・家族の相談窓口','こども家庭庁','全国／窓口により対象が異なります','子育て・学校・家庭など','https://www.cfa.go.jp/children-inquiries/','地域別の相談窓口を見る'],
 ['family','児童相談所の一覧','こども家庭庁','全国／各窓口の担当地域を確認','こどもと家庭に関する相談','https://www.cfa.go.jp/policies/jidougyakutai/jisou-ichiran/','児童相談所の公式情報を見る'],
 ['urgent','24時間子供SOSダイヤル','文部科学省','子ども・保護者など','いじめ・子どものSOS','https://www.mext.go.jp/a_menu/shotou/seitoshidou/1306988.htm','公式案内を確認する']
 ].map(([cat,name,owner,target,topic,url,btn])=>`<article class="support-item" data-category="${cat}"><h3>${E(name)}</h3><dl><dt>情報掲載</dt><dd>${E(owner)}</dd><dt>対象・地域</dt><dd>${E(target)}</dd><dt>相談内容</dt><dd>${E(topic)}</dd><dt>方法・費用</dt><dd>窓口の公式案内をご確認ください。</dd><dt>確認日</dt><dd>2026年10月1日</dd></dl>${cat==='urgent'?'<p>電話：<a href="tel:0120078310">0120-0-78310</a></p>':''}${external(url,btn)}</article>`).join('')}</div>${learningSupportList()}<h2>今すぐ安全の確保が必要なとき</h2><div class="emergency"><p>差し迫った危険があるときは、近くの信頼できる大人や、状況に応じて警察・救急に連絡してください。</p><p>警察：<a href="tel:110">110</a> ／ 救急・消防：<a href="tel:119">119</a></p><p>虐待かもしれないときの児童相談所虐待対応ダイヤル：<a href="tel:189">189</a></p>${external('https://www.cfa.go.jp/policies/jidougyakutai/gyakutai-taiou-dial/','189の公式案内を見る')}</div>`}
function content(id){
 const a=DATA.articles.find(a=>a.id===id);if(a)return article(a);
 const r=DATA.reports.find(a=>a.id===id);if(r)return subpage(id,r.summary,`<span class="pill">活動報告</span><p class="date">${E(r.date)}</p><p>${E(r.text)}</p>${external(r.url,'現行サイトの活動記事を見る')}<p class="meta">元記事確認日：2026年10月1日</p>`,'reports');
 switch(id){
 case 'home':return home();
 case 'concerns':return subpage(id,'今、気になることから選んでください。複数の困りごとがあってもかまいません。',audienceHub()+`<h2>困りごとから選ぶ</h2>`+articleCards('concerns',true), 'home',true);
 case 'school-life':return subpage(id,'学校との関わり方や、家庭での過ごし方、学びの選択肢を知るための情報です。',`<p>小中学生の学校生活、高校生の単位・進路・転学の迷い、保護者・先生の関わり方を考える情報です。</p>`+articleCards('school-life'),'home',true);
 case 'development':return subpage(id,'特性の現れ方や必要な支援は、一人ひとり異なります。診断を行うページではありません。',articleCards('development')+sources(['definitions','development-centers']),'home',true);
 case 'reports':return `<main id="main" tabindex="-1" class="demo-page"><section class="section"><div class="wrap"><nav class="breadcrumb" aria-label="現在位置">${link('home','ホーム')}<span>›</span><span>活動REPORT</span></nav><h1>活動REPORT</h1><p>センターの活動や、学びと支援に関する取り組みをご紹介します。</p>${reportDemoShell()}<section class="original-reports"><h2>これまでの活動</h2>${reportCards()}<p class="note">実際の活動の詳細は、各記事から現行サイトの報告をご覧いただけます。</p></section>${photo('reports','card')}${actions(link('home','ホームへ戻る','btn secondary'))}</div></section></main>`;
 case 'consult':return subpage(id,'相談方法によって、対象や受付条件が異なります。ご希望の方法をご確認ください。',`<div class="grid g2"><article class="card mint">${icon('phone')}<h2>電話で相談したい方へ</h2><p>小学生・中学生・高校生・成人の方を対象とする電話相談が案内されています。</p>${CONFIG.phoneApproved?'<p><a class="phone" href="tel:09046396036">090-4639-6036</a></p>':''}<p>現行サイトでは電話相談は無料と案内されています。対面・訪問などには有料のものもあります。</p>${actions(external('https://www.kodomoshien.jp/soudan.html','現行の受付条件を確認する'))}</article><article class="card">${icon('chat')}<h2>予約してオンラインで相談したい方へ</h2><p>現行サイトでは、わせがく高等学校との連携によるオンライン個別相談が案内されています。</p><p>対象学年・相談できる方・担当者を、予約案内でご確認ください。</p>${actions(link('booking','予約相談の対象と方法を見る','btn'))}</article></div><h2>本人・保護者・先生、それぞれの立場から</h2><p>小学生は、話しやすい大人と一緒に相談方法を確かめられます。中学生は高校進学、高校生は単位・卒業や転学・退学の迷いも相談のテーマになります。保護者は家庭での関わり方、先生は本人・家庭との連携を考える入口としてご利用ください。実際の窓口で相談できる方の条件をご確認ください。</p>${actions(link('school-life/future','高校の転校・転学・退学について','btn secondary'),link('concerns','立場や困りごとから探す','btn secondary'))}<h2>話す内容がまとまっていなくても</h2><p>気になっていること、本人が話していること、保護者が困っていることから相談できます。利用前に受付条件をご確認ください。</p><h2>センター以外の窓口も探せます</h2><p>地域や困りごとに合わせて、公的機関や専門窓口の情報をご案内しています。</p>${link('support','支援機関を探す','btn secondary')}`,'home',true);
 case 'booking':return bookingPage();
 case 'ai-guide':return navShell();
 case 'faq':return subpage(id,'相談の対象や利用方法について、よくある質問をまとめています。',faqBlock(DATA.faqs.length));
 case 'support':return subpage(id,'小中高校生・保護者・先生が、地域や困りごとに合う公的窓口や学びの相談先を探せます。',supportBody());
 case 'staff':return lecturersPage();
 case 'contact':return subpage(id,'教育相談や、講演・研修についてのお問い合わせ方法をご案内します。',`<h2>教育相談を希望する方へ</h2><p>相談方法ごとの対象と条件をご確認ください。相談の詳細を、このページへ入力する必要はありません。</p>${link('consult','相談方法を確認する','btn green')}<h2>講演・研修などのお問い合わせ</h2><p>小中高校生向けの学習会、保護者向けの相談会、先生向けの研修・フォーラム等への講師派遣をご案内しています。</p>${actions(link('staff','講師紹介と電話依頼を見る','btn secondary'))}${external('https://www.kodomoshien.jp/index.html','現行サイトで連絡方法を確認する')}<h2>予約について</h2><p>対象と受付条件、申込み後の連絡方法をご確認ください。</p>${link('booking','相談予約の案内を見る','btn secondary')}`);
 case 'about':return subpage(id,'小学生・中学生・高校生の健全育成を目指して、教育問題に関する研究、情報共有、実践活動を行う教育機関です。',`<h2>このポータルでできること</h2><p>困りごとに関する情報や、相談方法への入口を探せます。センター以外の公的な窓口も含めて、今の状況に合う選択肢を確認するための情報をご案内します。</p><h2>活動内容</h2><div class="grid g2">${card('教育相談','本人・保護者・先生が、今の状況から相談方法を確認できます。','consult','教育相談の案内','phone')}${card('講師派遣','相談会・フォーラム・学校やPTAの研修などへの派遣を電話で依頼できます。','staff','講師紹介と派遣依頼を見る','people')}${card('活動の情報発信','活動レポートをご覧いただけます。担当者向けの投稿・プレビュー体験もあります。','reports','活動レポートを見る','book')}${card('相談予約の体験','日付・時刻・立場・相談内容を選ぶ仮想予約を試せます。','booking','相談予約を体験する','chat')}</div><h2>このポータルの案内機能</h2>${actions(link('concerns','立場・困りごとから探す','btn secondary'),link('school-life/future','高校の転学・退学の案内','btn secondary'),link('support','相談・支援機関を探す','btn secondary'),link('ai-guide','教育支援ナビを使う','btn ai'),link('faq','よくある質問','btn secondary'),link('contact','お問い合わせ','btn secondary'))}<h2>活動と連携</h2><p>教育サポート相談や、保護者・教育関係者に向けたフォーラムなどの活動が現行サイトで紹介されています。</p><p>オンライン個別相談については、わせがく高等学校との連携が現行の予約ページに明記されています。相談方法ごとの担当と受付条件をご確認ください。</p>${CONFIG.operator?'<h2>運営主体</h2><p>'+E(CONFIG.operator)+'</p>':''}<h2>センターの公式情報</h2>${external('https://www.kodomoshien.jp/index.html','現行のセンターサイトを見る')}${actions(link('reports','活動REPORTを見る','btn secondary'),link('consult','相談方法を見る','btn green'))}`);
 case 'privacy':return subpage(id,'相談や外部サービスを利用する前に、個人情報の取扱いをご確認ください。',`<h2>このページ内の入力</h2><p>教育支援ナビの体験版には自由入力欄がありますが、氏名、住所、学校名など個人を特定できる情報は入力しないでください。入力はブラウザー内だけで処理し、外部への送信や保存は行いません。会話の選択状態はページを閉じると消えます。</p><h2>投稿・予約の体験機能</h2><p>活動レポートの文章・写真・動画と、仮想予約の選択内容はページ内だけで扱います。外部への送信や永続保存はしません。ページを離れると消えます。実際の個人情報を含む文章や画像は入力しないでください。</p><h2>予約や外部サービス</h2><p>実際の予約は外部の受付ページで行います。利用する窓口のプライバシーポリシー、入力内容、連絡方法をご確認ください。</p><h2>このサイトの提供サービスと掲載コンテンツ</h2><p>サイトを提供するサービスや、外部のコンテンツにも、それぞれのデータ取扱い条件があります。</p>${CONFIG.privacyText?'<h2>運営者からのご案内</h2><p>'+E(CONFIG.privacyText)+'</p>':''}<h2>取扱いについての問い合わせ</h2><p>運営者の個人情報の取扱いは、センターの連絡窓口にご確認ください。</p>${link('contact','お問い合わせ方法を見る','btn secondary')}`);
 case 'site-policy':return subpage(id,'掲載情報の利用と、外部ページへのリンクについてご案内します。',`<h2>情報の使い方</h2><p>掲載情報は相談先を探し、確認したいことを整理するためのものです。個別の状況に対する診断や治療、支援内容の確約を行うものではありません。</p><h2>最新の受付条件</h2><p>相談の対象、費用、日時などは変わる場合があります。実際に利用する窓口の最新の案内をご確認ください。</p><h2>外部ページのリンク</h2><p>外部ページは別のタブで開きます。リンク先の情報、利用条件は、その提供元の案内をご確認ください。</p><h2>画像と文章</h2><p>掲載写真はAIで生成した案内用のイメージです。実際の施設、相談員、利用者、開催イベントの写真ではありません。人物から診断や特性を判断するものでもありません。文章や画像の再利用については、センターにお問い合わせください。</p>${link('contact','お問い合わせ方法を見る','btn secondary')}`);
 case 'ai-policy':return subpage(id,'教育支援ナビの体験版について、利用方法と情報の扱いをご案内します。',`<h2>現在の提供状況</h2><p>教育支援ナビは、APIや実際のAIに接続しない体験版です。選択肢と固定の案内、短い言葉のルールによって、関連する情報や相談先を表示します。自由なAI回答やRAGによる検索ではありません。</p><h2>情報案内の目的</h2><p>AIを導入する場合も、情報や相談先を探すための案内役として扱い、診断や治療を行うものにはしません。</p><h2>入力と会話の扱い</h2><p>氏名、学校名、住所など、個人を特定できる情報は入力しないでください。入力はブラウザー内で処理し、外部へ送信しません。文章自体は会話履歴に再表示せず、会話中の選択だけを保持します。ページを閉じると消え、他のページから戻った場合も最初からになります。</p><p>個人情報や危険な状況の自動検出は、すべての書き方に対応できるものではありません。今の危険があるときは、人への連絡を優先してください。</p><h2>相談先の表示</h2><p>電話番号・受付情報・URLは固定の相談先マスタから表示します。文章を自動生成して番号やリンクを作ることはありません。</p><h2>人への相談と通常の案内</h2><p>AIの有無にかかわらず、困りごとの情報と人への相談窓口をご利用いただけます。</p>${actions(link('concerns','困りごとから探す','btn'),link('consult','人への相談方法を見る','btn green'))}`);
 default:throw Error('No page renderer '+id);
 }
}
function renderPage(id){return header(id)+(CONFIG.publicationApproved?'':'<div class="wrap"><p class="note">公開前の確認用ページです。相談の利用条件は現行の案内をご確認ください。</p></div>')+content(id)+footer()}
function bindPage(){
 if(typeof navBind==='function')navBind();
 reportDemoBind();bookingBind();
 const menu=document.querySelector('.menu-button');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.getElementById('primary-nav').classList.toggle('open',open)});
 const region=document.getElementById('region'),category=document.getElementById('category');
 if(region&&category){const update=()=>{let count=0;document.querySelectorAll('.support-item').forEach(el=>{el.hidden=category.value!=='all'&&el.dataset.category!==category.value;if(!el.hidden)count++});const names={chiba:'千葉県',saitama:'埼玉県',tokyo:'東京都',ibaraki:'茨城県'};document.getElementById('regional-links').innerHTML=region.value==='all'?'':`<p>${E(names[region.value])}の相談窓口は、こども家庭庁の地域別案内から確認できます。</p>`+external('https://www.cfa.go.jp/children-inquiries/'+region.value+'/',names[region.value]+'の公式案内を見る');document.getElementById('support-status').textContent=count+'件の公式情報への入口を表示しています。地域ごとの対象は公式情報をご確認ください。'};region.addEventListener('change',update);category.addEventListener('change',update);update();}
}
function initialRoute(){const match=location.hash.match(/^#page=(.+)$/);if(match){try{const id=decodeURIComponent(match[1]);if(Object.hasOwn(ROUTES,id))return id}catch{}}return CONFIG.initialPage||'home'}
function loadPage(id,focus=false){document.getElementById('app').innerHTML=renderPage(id);document.title=ROUTES[id]+' | 子ども教育支援センター';bindPage();if(focus){window.scrollTo({top:0,behavior:'instant'});document.getElementById('main')?.focus({preventScroll:true})}}
if(typeof document!=='undefined'&&document.getElementById('app')){
 document.addEventListener('click',event=>{const anchor=event.target.closest('a[data-internal]');if(!anchor||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();const id=anchor.dataset.page;const hash='#page='+encodeURIComponent(id);if(location.hash===hash){loadPage(id,true);return}location.hash=hash;});
 window.addEventListener('hashchange',()=>{if(!location.hash||location.hash.startsWith('#page='))loadPage(initialRoute(),true)});
 loadPage(initialRoute());
}
